<!-- This file is generated by AI. -->
<!--
  引擎 / 模板管理 (**内联**在设置对话框里, 不是子对话框 —— 弹一层壳只会少一屏信息)。

  两者都是**引用式**的: 设置里只记磁盘路径, 不复制内容, 删掉一项不会动磁盘上的文件 ——
  界面上要说清楚, 否则用户不敢点。

  必须保留的行为: 添加模板走 `validateTemplate()` 并采用它返回的 `name` / `manifestId` ——
  `resolveProjectTemplate` 拿这两个字段与项目里的 `template.json` 比对, 只存目录名会让匹配永远
  不成立 (界面一直显示「模板（未知）」); 添加引擎走 `validateEngine()` (缺 index.html 当场拒绝)
  并查重复路径; 引擎条目标出「当前项目正在使用」; 移除前确认。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css` (`.manager-*` 一族)。
-->
<script lang="ts">
  import { open as openDialog } from '@tauri-apps/plugin-dialog';

  import { requestConfirm } from '../confirm';
  import { makeEngineEntry } from '../lib/engine';
  import { validateEngine } from '../lib/engineDir';
  import { createId, validateTemplate } from '../lib/engineTemplate';
  import type { EngineEntry, TemplateEntry } from '../lib/settings';
  import { actions, appStore } from '../state/store.svelte';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';

  let { kind }: { kind: 'engine' | 'template' } = $props();

  let busy = $state(false);
  let error = $state<string | null>(null);

  const engines = $derived(appStore.settings.engines);
  const templates = $derived(appStore.settings.templates);
  const projectPath = $derived(appStore.projectPath);
  const isEngine = $derived(kind === 'engine');
  const title = $derived(isEngine ? '引擎' : '模板');
  const entries = $derived<(EngineEntry | TemplateEntry)[]>(isEngine ? engines : templates);

  /** 当前项目绑定了哪个引擎 (用于在清单里标出"这个正在被用")。 */
  const boundEngineId = $derived.by(() => {
    const path = projectPath;
    if (!path) return null;
    const key = path.replace(/\\/g, '/').toLowerCase();
    const binding = Object.entries(appStore.projectBindings).find(
      ([entryKey]) => entryKey.replace(/\\/g, '/').toLowerCase() === key
    )?.[1];
    return binding?.engineId ?? null;
  });

  /** 包一层: 选目录/校验都可能抛 (权限、路径异常), 统一变成界面上的错误行。 */
  async function run(action: () => Promise<unknown>): Promise<void> {
    busy = true;
    error = null;
    try {
      await action();
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  async function pickDirectory(askTitle: string): Promise<string | null> {
    try {
      const path = await openDialog({ title: askTitle, directory: true, multiple: false });
      return typeof path === 'string' && path ? path : null;
    } catch {
      // 用户取消不是错误
      return null;
    }
  }

  async function addEngine(): Promise<void> {
    const target = await pickDirectory('选择 WebGAL 引擎目录');
    if (!target) return;
    await run(async () => {
      // 先确认它确实是个引擎 (至少有 index.html), 避免"加进来了但预览白屏"
      const check = await validateEngine(target);
      if (!check.valid) throw new Error(check.error ?? '这不是一个可用的 WebGAL 引擎目录');
      if (engines.some((engine) => engine.path === target)) throw new Error('该引擎已添加');
      actions.updateSettings({
        engines: [
          ...engines,
          makeEngineEntry(target, { name: check.name, version: check.version, manifestId: check.manifestId }),
        ],
      });
    });
  }

  async function addTemplate(): Promise<void> {
    const target = await pickDirectory('选择项目模板目录');
    if (!target) return;
    await run(async () => {
      const check = await validateTemplate(target);
      if (!check.valid) throw new Error(check.error ?? '这不是一个可用的模板目录');
      if (templates.some((template) => template.path === target)) throw new Error('该模板已添加');
      actions.updateSettings({
        templates: [...templates, { id: createId(), name: check.name, manifestId: check.manifestId, path: target }],
      });
    });
  }

  function remove(entry: EngineEntry | TemplateEntry): void {
    const inUse = isEngine && entry.id === boundEngineId;
    requestConfirm({
      title: `移除${title}`,
      description: inUse
        ? `「${entry.name}」正被当前项目使用。移除后该项目会回落到清单里的第一个引擎，磁盘上的目录不会被删除。`
        : `从清单里移除「${entry.name}」。磁盘上的目录不会被删除。`,
      confirmLabel: '移除',
      danger: true,
      action: () => {
        if (isEngine) {
          actions.updateSettings({ engines: engines.filter((item) => item.id !== entry.id) });
        } else {
          actions.updateSettings({ templates: templates.filter((item) => item.id !== entry.id) });
        }
      },
    });
  }
</script>

<section class="manager-section">
  <!-- `.manager-section-head` 是 space-between: 标题在左、添加按钮在最右 -->
  <div class="manager-section-head">
    <h3 class="manager-section-title">{title}</h3>
    <Button
      appearance="primary"
      icon="Add"
      disabled={busy}
      onclick={() => void (isEngine ? addEngine() : addTemplate())}
    >
      添加{title}
    </Button>
  </div>

  {#if entries.length === 0}
    <p class="muted">
      {isEngine ? '尚未添加引擎 (项目需自包含 index.html)' : '尚未添加模板 (默认使用引擎内置模板)'}
    </p>
  {:else}
    <ul class="manager-list">
      {#each entries as entry (entry.id)}
        <li class="manager-item" title={entry.path}>
          <Icon name={isEngine ? 'FolderOpen' : 'Document'} size={15} />
          <div class="manager-item-content">
            <div class="manager-item-heading">
              <span class="manager-item-name">{entry.name}</span>
              {#if isEngine}
                <!--
                  版本读不到时明说"版本未知", 而不是空白。
                  用 `'version' in entry` 而不是 `isEngine`: 后者是布尔量, TS 不会据此收窄联合类型。
                -->
                {#if 'version' in entry && entry.version}
                  <span class="manager-item-version">v{entry.version}</span>
                {:else}
                  <span class="manager-item-version">版本未知</span>
                {/if}
              {:else}
                <span class="manager-item-version"
                  >ID: {'manifestId' in entry ? (entry.manifestId ?? '未知') : '未知'}</span
                >
              {/if}
              {#if isEngine && entry.id === boundEngineId}
                <span class="manager-item-version">（当前项目正在使用）</span>
              {/if}
            </div>
            <span class="manager-item-path">{entry.path}</span>
          </div>
          <button
            type="button"
            class="manager-item-remove"
            title="移除（不会删除磁盘上的目录）"
            aria-label="移除"
            disabled={busy}
            onclick={() => remove(entry)}
          >
            <Icon name="Delete" size={14} />
          </button>
        </li>
      {/each}
    </ul>
  {/if}

  {#if isEngine}
    <p class="manager-hint">引擎在“项目”页里逐个项目选择；目录里带 index.html 的项目用项目内置引擎。</p>
  {:else}
    <p class="manager-hint">模板按清单里的 name + ID 与项目匹配；没有匹配上时界面会显示「模板（未知）」。</p>
  {/if}

  {#if error}
    <p class="prompt-error">{error}</p>
  {/if}
</section>
